# 113 "stack.cpp"
typedef int TYPE_DATA_ELEMENTS;

const int COEF_REALLOC_INCREASE = 2;
const int COEF_REALLOC_REDUCE = 4;

const int POISON = 67676767;

enum struct_error_t {

    SUCCESS_FINISH_FUNCTION = 0,
    INIT_ERROR_LACK_OF_MEMORY = 1,
    PUSH_ELEMENT_ERROR_LACK_OF_MEMORY = 2,
    POP_ELEMENT_ERROR_LACK_OF_MEMORY = 3,


    ERROR_INCORRECT_CAPACITY = 4,
    ERROR_NULL_DATA = 5,
    ERROR_SIZE_LESS_THAN_ZERO = 6,
    ERROR_NULL_PTR_ON_STRUCT = 7,
    ERROR_SIZE_MORE_THAN_CAPACITY = 8,
    ERROR_SIZE_VALUE_NOT_POISONED = 9,
    ERROR_POPED_ELEMENT_IS_POISONED = 10,
    ERROR_STACK_IS_EMPTY_TO_POP = 15,



    LEFT_CANARY_DISTRUCTED = 11,
    RIGHT_CANARY_DISTRUCTED = 12,



    HASHES_STRUCT_NOT_MATCH = 13,
    HASHES_DATA_NOT_MATCH = 14,

};

struct stack_info_t {


        long long hash_struct;
        long long hash_data;


    TYPE_DATA_ELEMENTS* real_data;
    ssize_t capacity;
    ssize_t size;
    struct_error_t struct_error;


    TYPE_DATA_ELEMENTS* data_with_canaries;
    long long left_canary;
    long long right_canary;



        TYPE_DATA_ELEMENTS last_popped_element;
        TYPE_DATA_ELEMENTS last_pushed_element;
        int str_code_failure;
        const char* func_failure;

};

struct_error_t stack_init(stack_info_t* stack_info, ssize_t capacity);
struct_error_t stack_push(stack_info_t* stack_info, TYPE_DATA_ELEMENTS push_element);
struct_error_t stack_pop(stack_info_t* stack_info, TYPE_DATA_ELEMENTS* pop_element);
struct_error_t stack_verify(stack_info_t* stack_info);
void fill_the_array_poison(stack_info_t* stack_info);
struct_error_t check_empty_stack_for_pop(stack_info_t* stack_info);
long long hash_function_for_struct(stack_info_t* stack_info);
long long hash_function_for_data(stack_info_t* stack_info);
void stack_destroy(stack_info_t* stack_info);
void stack_dump(stack_info_t stack_info);

int main() {

    struct stack_info_t stack_info = {};

    stack_init(&stack_info, 1);




    int x1 = 0;


    stack_pop(&stack_info, &x1);



    for(ssize_t i = 0; i<stack_info.capacity; i++) {
        printf("%d \n", stack_info.real_data[i]);
    }



    return 0;
}

struct_error_t stack_init(stack_info_t* stack_info, ssize_t capacity) {

    stack_info -> struct_error = SUCCESS_FINISH_FUNCTION;

    void* temp = realloc(stack_info -> data_with_canaries, sizeof(TYPE_DATA_ELEMENTS) * capacity + 2 * sizeof(long long));
    if (temp == 0LL) {
        stack_info -> struct_error = INIT_ERROR_LACK_OF_MEMORY;
        stack_info -> str_code_failure = 218; stack_info -> func_failure = __func__; stack_verify(stack_info); return(stack_info -> struct_error);
    }

    stack_info -> data_with_canaries = (TYPE_DATA_ELEMENTS*)temp; stack_info -> real_data = (TYPE_DATA_ELEMENTS*)((char*)temp + sizeof(long long));

    stack_info -> capacity = capacity;
    stack_info -> size = 0;


    fill_the_array_poison(stack_info);

    stack_info -> left_canary = 0xEBA1CB0E04E10; stack_info -> right_canary = 0xEBA1DEDA; *((long long*)stack_info -> data_with_canaries) = stack_info -> left_canary; *((long long*)(stack_info -> real_data + capacity)) = stack_info -> right_canary;

    hash_function_for_data(stack_info);
    hash_function_for_struct(stack_info);

    return SUCCESS_FINISH_FUNCTION;
}

struct_error_t stack_push(stack_info_t* stack_info, TYPE_DATA_ELEMENTS push_element) {

    stack_verify(stack_info); if (stack_info -> struct_error != SUCCESS_FINISH_FUNCTION) { stack_info -> str_code_failure = 239; stack_dump(*stack_info); return (stack_info -> struct_error); }

    if ((stack_info -> size) == (stack_info -> capacity)) {
        printf("The size of stack is not enough. Current capacity = %zu," " increase to capacity = %zu\n", stack_info -> capacity, (stack_info -> capacity) * COEF_REALLOC_INCREASE);

        void* temp = realloc(stack_info -> data_with_canaries, sizeof(TYPE_DATA_ELEMENTS) * stack_info -> capacity + 2 * sizeof(long long));

        if (temp == 0LL) {
            stack_info -> struct_error = PUSH_ELEMENT_ERROR_LACK_OF_MEMORY;
            stack_info -> str_code_failure = 248; stack_info -> func_failure = __func__; stack_verify(stack_info); return(stack_info -> struct_error);
        }

        stack_info -> data_with_canaries = (TYPE_DATA_ELEMENTS*)temp; stack_info -> real_data = (TYPE_DATA_ELEMENTS*)((char*)temp + sizeof(long long));

        (stack_info -> capacity) *= COEF_REALLOC_INCREASE;
        fill_the_array_poison(stack_info);

        *((long long*)(stack_info -> real_data + stack_info -> capacity)) = stack_info -> right_canary;
    }

    (stack_info -> real_data)[stack_info -> size] = push_element;
    stack_info -> last_pushed_element = (stack_info -> real_data)[stack_info -> size];

    (stack_info -> size)++;

    hash_function_for_data(stack_info);
    hash_function_for_struct(stack_info);

    return SUCCESS_FINISH_FUNCTION;
}

struct_error_t stack_pop(stack_info_t* stack_info, TYPE_DATA_ELEMENTS* pop_element) {

    stack_verify(stack_info); if (stack_info -> struct_error != SUCCESS_FINISH_FUNCTION) { stack_info -> str_code_failure = 272; stack_dump(*stack_info); return (stack_info -> struct_error); }

    if (check_empty_stack_for_pop(stack_info) == ERROR_STACK_IS_EMPTY_TO_POP) { stack_info -> str_code_failure = 274; stack_info -> func_failure = __func__; return(stack_info -> struct_error); }
    (stack_info -> size)--;

    *pop_element = (stack_info -> real_data)[stack_info -> size];
    stack_info -> last_popped_element = (stack_info -> real_data)[stack_info -> size];
    (stack_info -> real_data)[stack_info -> size] = POISON;

    if ((stack_info -> capacity) / COEF_REALLOC_REDUCE == (stack_info -> size)) {
        stack_info -> capacity /= COEF_REALLOC_REDUCE;
        printf("New capacity of data_with_canaries = %zu, size = %zu\n", stack_info -> capacity, stack_info -> size);
        void* temp = realloc(stack_info -> data_with_canaries, sizeof(TYPE_DATA_ELEMENTS) * stack_info -> capacity + 2 * sizeof(long long));

        if (temp == 0LL) {
            stack_info -> struct_error = POP_ELEMENT_ERROR_LACK_OF_MEMORY;
            stack_info -> str_code_failure = 288; stack_info -> func_failure = __func__; stack_verify(stack_info); return(stack_info -> struct_error);
        }
        stack_info -> data_with_canaries = (TYPE_DATA_ELEMENTS*)temp; stack_info -> real_data = (TYPE_DATA_ELEMENTS*)((char*)temp + sizeof(long long));

        *((long long*)(stack_info -> real_data + stack_info -> capacity)) = stack_info -> right_canary;
    }

    hash_function_for_data(stack_info);
    hash_function_for_struct(stack_info);

    return SUCCESS_FINISH_FUNCTION;
}

void stack_destroy(stack_info_t* stack_info) {

    free(stack_info -> data_with_canaries);
    free(stack_info -> real_data);

    stack_info -> data_with_canaries = 0LL;
    stack_info -> real_data = 0LL;
    stack_info -> capacity = 0;
    stack_info -> size = 0;


    stack_info -> left_canary = 0;
    stack_info -> right_canary = 0;



    stack_info -> last_pushed_element = POISON;
    stack_info -> last_popped_element = POISON;



    stack_info -> hash_struct = 0;
    stack_info -> hash_data = 0;


}


void stack_dump(stack_info_t stack_info) {

    printf("\033[34m" "Print information about stack because of failure № %d:\n"
            "failure code line %d;\n"
            "name function name failure <%s>;\n",
            stack_info.struct_error,
            stack_info.str_code_failure,
            stack_info.func_failure);
    printf("\033[34m" "capacity = %zd;\n", stack_info.capacity);
    printf("\033[34m" "size = %zd;\n", stack_info.size);
    printf("\033[34m" "data_with_canaries = %p\n", stack_info.data_with_canaries);
    printf("\033[34m" "real data_with_canaries = %p\n", stack_info.real_data);
    printf("\033[34m" "last pushed element = %d\n", stack_info.last_pushed_element);
    printf("\033[34m" "last popped element = %d\n", stack_info.last_popped_element);
    printf("\033[34m" "real data_with_canaries = %p\n", stack_info.real_data);

    printf("\033[34m" "Left canary = %llx, Right canary = %llx\n", stack_info.left_canary, stack_info.right_canary);
    printf("\033[34m" "Current left canary = %llx, Current right canary = %llx\n" "\033[37m",
                                    *(long long*)stack_info.data_with_canaries, *(long long*)(stack_info.real_data + stack_info.capacity));


    for (ssize_t i = 0; i < stack_info.size; i++) {
        printf("\033[32m" "\t*[%zd] = %d\n" "\033[37m", i, stack_info.real_data[i]);
    }

    for (ssize_t i = stack_info.size; i < stack_info.capacity; i++) {
        printf("\033[37m" "\t[%zd] = %d\n", i, stack_info.real_data[i]);
    }

    printf("\033[37m" "-------------------------------------\n");
}

struct_error_t stack_verify(stack_info_t* stack_info) {

    if (stack_info == 0LL) {
        stack_info -> struct_error = ERROR_NULL_PTR_ON_STRUCT;
    }
    else {
        if (stack_info -> struct_error != SUCCESS_FINISH_FUNCTION) {
            stack_dump(*stack_info);
            return (stack_info -> struct_error);
        }

        if (stack_info -> data_with_canaries == 0LL) {
            stack_info -> str_code_failure = 373;
            stack_info -> struct_error = ERROR_NULL_DATA;
        }

        else if (*(long long*)(stack_info -> data_with_canaries) != stack_info -> left_canary) {
            stack_info -> str_code_failure = 378;
            stack_info -> struct_error = LEFT_CANARY_DISTRUCTED;
        }
        else if (*(long long*)(stack_info -> real_data + stack_info -> capacity) != stack_info -> right_canary) {
            stack_info -> str_code_failure = 382;
            stack_info -> struct_error = RIGHT_CANARY_DISTRUCTED;
        }



        if (hash_function_for_struct(stack_info) != stack_info -> hash_struct) {
            stack_info -> struct_error = HASHES_STRUCT_NOT_MATCH;
        }

        if (hash_function_for_struct(stack_info) != stack_info -> hash_data) {
            stack_info -> struct_error = HASHES_DATA_NOT_MATCH;
        }


        else if (stack_info -> capacity <= 0) {
            stack_info -> struct_error = ERROR_INCORRECT_CAPACITY;
        }
        else if (stack_info -> size < 0) {
            stack_info -> struct_error = ERROR_SIZE_LESS_THAN_ZERO;
        }
        else if ((stack_info -> size) > (stack_info -> capacity)) {
            stack_info -> struct_error = ERROR_SIZE_MORE_THAN_CAPACITY;
        }
        else if (stack_info -> last_popped_element == POISON) {
            stack_info -> struct_error = ERROR_POPED_ELEMENT_IS_POISONED;
        }
        else if ((stack_info -> real_data)[stack_info -> size] != POISON && stack_info -> size < stack_info -> capacity -1) {
            stack_info -> struct_error = ERROR_SIZE_VALUE_NOT_POISONED;
        }
    }


    if (stack_info -> struct_error != SUCCESS_FINISH_FUNCTION) {
        stack_info -> func_failure = __func__;
        stack_dump(*stack_info);
    }

    return (stack_info -> struct_error);
}

void fill_the_array_poison(stack_info_t* stack_info) {
    for (ssize_t i = stack_info -> size; i < stack_info -> capacity; i++) {
        (stack_info -> real_data)[i] = POISON;
    }
}

struct_error_t check_empty_stack_for_pop(stack_info_t* stack_info) {
    if (stack_info -> size <= 0) {
        stack_info -> struct_error = ERROR_STACK_IS_EMPTY_TO_POP;
    }
    return stack_info -> struct_error;
}



long long hash_function_for_struct(stack_info_t* stack_info) {

    long long hash_struct = 0;
    for(size_t i = 0; i < sizeof(stack_info_t) - sizeof(stack_info -> hash_struct) - sizeof(stack_info -> hash_data); i++) {
        hash_struct += ((char*)((char*)stack_info + sizeof(stack_info -> hash_struct) + sizeof(stack_info -> hash_data)))[i];
    }
    return hash_struct;
}

long long hash_function_for_data(stack_info_t* stack_info) {

    long long hash_data = 0;
    for(size_t i = 0; i < stack_info -> capacity * sizeof(TYPE_DATA_ELEMENTS); i++) {
        hash_data += ((char*)(stack_info -> real_data))[i];
    }
    return hash_data;
}
